package android.database.sqlite;import android.content.Context;import android.database.Cursor;public abstract class SQLiteOpenHelper implements AutoCloseable{private SQLiteDatabase db;private final String path;private final int version;public SQLiteOpenHelper(Context c,String name,Object factory,int version){this.path=c.root+"/"+name;this.version=version;}public void setWriteAheadLoggingEnabled(boolean enabled){}public void onConfigure(SQLiteDatabase db){}public abstract void onCreate(SQLiteDatabase db);public abstract void onUpgrade(SQLiteDatabase db,int old,int next);public SQLiteDatabase getWritableDatabase(){if(db==null){db=new SQLiteDatabase(path);onConfigure(db);int old;try(Cursor c=db.rawQuery("PRAGMA user_version",null)){c.moveToFirst();old=c.getInt(0);}if(old<version){db.beginTransaction();try{if(old==0)onCreate(db);else onUpgrade(db,old,version);db.execSQL("PRAGMA user_version="+version);db.setTransactionSuccessful();}finally{db.endTransaction();}}else if(old>version)throw new IllegalStateException("Newer database");}return db;}public SQLiteDatabase getReadableDatabase(){return getWritableDatabase();}public void close(){if(db!=null){db.close();db=null;}}}
